import{_ as h,C as e,o as n,c as r,a2 as i,b as c,w as a,a as s,E as d,a3 as l}from"./chunks/framework.O93z6AWZ.js";const v=JSON.parse('{"title":"Đề tài 3.2 — Sa sút trí tuệ (dữ liệu khuyết)","description":"","frontmatter":{"title":"Đề tài 3.2 — Sa sút trí tuệ (dữ liệu khuyết)"},"headers":[],"relativePath":"du_an/sa_sut_tri_tue.md","filePath":"du_an/sa_sut_tri_tue.md"}'),u={name:"du_an/sa_sut_tri_tue.md"};function g(m,t,b,p,k,_){const o=e("Mermaid");return n(),r("div",null,[t[1]||(t[1]=i('<h1 id="đe-tai-3-2-xu-ly-du-lieu-khuyet-thang-điem-nhan-thuc-mmse-moca-trong-sang-loc-sa-sut-tri-tue" tabindex="-1">Đề tài 3.2: Xử lý dữ liệu khuyết thang điểm nhận thức (MMSE/MoCA) trong sàng lọc Sa sút trí tuệ <a class="header-anchor" href="#đe-tai-3-2-xu-ly-du-lieu-khuyet-thang-điem-nhan-thuc-mmse-moca-trong-sang-loc-sa-sut-tri-tue" aria-label="Permalink to &quot;Đề tài 3.2: Xử lý dữ liệu khuyết thang điểm nhận thức (MMSE/MoCA) trong sàng lọc Sa sút trí tuệ&quot;">​</a></h1><p><strong>Nhóm đề tài:</strong> 3. Bệnh án Điện tử &amp; Dữ liệu Bảng (Clinical Tabular &amp; EHR) · <strong>Trạng thái:</strong> ✅ Y văn khởi động đầy đủ · ⏳ Workflow/timeline theo mẫu chung</p><div class="tip custom-block"><p class="custom-block-title">📥 Bộ tài liệu đầy đủ trên GitHub</p><p>Dữ liệu thô và mã nguồn chi tiết được lưu trữ <strong>Private</strong> trên kho GitHub của bộ môn (để đảm bảo sinh viên tự thực hiện). Sinh viên tham khảo thông tin mức độ cơ bản tại đây.</p></div><p>Đọc trước <strong><a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a></strong>.</p><hr><h2 id="_1-phat-bieu-bai-toan" tabindex="-1">1. Phát biểu bài toán <a class="header-anchor" href="#_1-phat-bieu-bai-toan" aria-label="Permalink to &quot;1. Phát biểu bài toán&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Câu hỏi nghiên cứu</strong></td><td>Xử lý dữ liệu khuyết ở các thang điểm sàng lọc nhận thức (MMSE/MoCA/CDR) trong dữ liệu đa phương thức sa sút trí tuệ mà không gây sai lệch chẩn đoán</td></tr><tr><td><strong>Input (X)</strong></td><td>Dữ liệu lâm sàng đa phương thức (nhân khẩu học, xét nghiệm, hình ảnh học) có tỷ lệ khuyết cao ở các thang điểm nhận thức</td></tr><tr><td><strong>Output (Y)</strong></td><td>Giá trị điền khuyết (imputed) của MMSE/MoCA/CDR, hoặc phân loại MCI vs Dementia sau khi điền khuyết</td></tr><tr><td><strong>Dataset gợi ý</strong></td><td>ADNI (Alzheimer&#39;s Disease Neuroimaging Initiative) hoặc OASIS</td></tr><tr><td><strong>Thách thức đặc thù</strong></td><td>Nội suy dữ liệu nhưng <strong>không gây &quot;Artificial Normalcy&quot;</strong> — làm sai lệch ranh giới chẩn đoán giữa MCI và Dementia khi điền khuyết quá &quot;trung bình hóa&quot;</td></tr></tbody></table><hr><h2 id="_2-y-van-khoi-đong-4-bai-—-toan-bo-include" tabindex="-1">2. Y văn khởi động (4 bài — toàn bộ INCLUDE) <a class="header-anchor" href="#_2-y-van-khoi-đong-4-bai-—-toan-bo-include" aria-label="Permalink to &quot;2. Y văn khởi động (4 bài — toàn bộ INCLUDE)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Citekey</th><th>Tóm tắt</th></tr></thead><tbody><tr><td><code>aracri2025bridging</code></td><td>So sánh 5 phương pháp impute (mean/median/kNN/MICE/missForest) × 3 classifier trên MMSE/MoCA — MICE tốt nhất cho RF/LR (0,76/0,81)</td></tr><tr><td><code>haridas2024autoencoder</code></td><td>Denoising autoencoder impute dữ liệu ADNI đa phương thức bao gồm CDR (N=559), accuracy 0,79–0,89</td></tr><tr><td><code>aghili2022addressing</code></td><td>Gradient Boosting xử lý khuyết nội tại trên dữ liệu đa phương thức</td></tr><tr><td><code>niamh2021practica</code></td><td>Xử lý dữ liệu khuyết cực đoan (~50%) mô phỏng thực tế phòng khám trí nhớ</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination trong thực tế</p><p>2/4 bài (<code>aghili2022addressing</code>, <code>niamh2021practica</code>) <strong>chưa có số liệu định lượng đầy đủ</strong> — chỉ tìm được kết luận định tính, không có số liệu cụ thể để tránh tự suy diễn/bịa số liệu. <strong>Đây là việc đầu tiên sinh viên cần làm</strong>: đọc toàn văn 2 bài này để bổ sung số liệu định lượng thật trước khi dùng trong báo cáo.</p></div><h3 id="so-đo-prisma" tabindex="-1">Sơ đồ PRISMA <a class="header-anchor" href="#so-đo-prisma" aria-label="Permalink to &quot;Sơ đồ PRISMA&quot;">​</a></h3>',12)),(n(),c(l,null,{default:a(()=>[d(o,{id:"mermaid-130",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A5%5B%22WebSearch%20%2B%20Crossref%20verify%3A%204%22%5D%20--%3E%20TOTAL_ID%5B%22T%E1%BB%95ng%20s%E1%BB%91%20b%E1%BA%A3n%20ghi%3Cbr%3EN%20%3D%204%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20FINAL_INC%5B%22INCLUDE%20v%C3%A0o%20Evidence%20Matrix%3Cbr%3EN%20%3D%204%20(0%20EXCLUDE)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Áp dụng workflow 7 giai đoạn / timeline 15 tuần chung (xem mẫu chi tiết ở <a href="/hmyt-book/du_an/roi_loan_nhip_tim">Đề tài 1.2 — Rối loạn nhịp tim</a>). Lưu ý đặc thù dữ liệu khuyết:</p><ul><li><strong>gd2-dataset-eda:</strong> trực quan hóa <strong>mô hình khuyết dữ liệu</strong> (Missing Completely at Random / Missing at Random / Missing Not at Random) bằng ma trận missingness (vd. thư viện <code>missingno</code>) — bắt buộc trước khi chọn phương pháp impute.</li><li><strong>gd3-preprocessing:</strong> thử nghiệm ≥2 phương pháp impute (khuyến nghị theo <code>aracri2025bridging</code>: mean/median làm baseline, MICE/kNN làm phương pháp chính) — <strong><code>fit</code> bộ imputer CHỈ trên Train</strong>, tuyệt đối không impute trên toàn bộ dataset trước khi chia tập (đây là một dạng data leakage tinh vi, dễ bị bỏ sót).</li><li><strong>gd4/gd5:</strong> so sánh hiệu năng downstream (phân loại MCI/Dementia) giữa các chiến lược impute khác nhau — đây chính là &quot;ablation study&quot; tự nhiên của đề tài này.</li><li><strong>gd6-evaluation-xai:</strong> phân tích xem việc impute có làm dịch chuyển phân phối gần ranh giới quyết định không (kiểm tra &quot;Artificial Normalcy&quot;) — dùng SHAP để xem đặc trưng bị impute có bị mô hình dùng quá mức không.</li></ul><hr><h2 id="_4-viec-con-ton-đong-tu-bao-cao-y-van" tabindex="-1">4. Việc còn tồn đọng (từ báo cáo y văn) <a class="header-anchor" href="#_4-viec-con-ton-đong-tu-bao-cao-y-van" aria-label="Permalink to &quot;4. Việc còn tồn đọng (từ báo cáo y văn)&quot;">​</a></h2><ol><li><strong>Ưu tiên cao:</strong> bổ sung số liệu định lượng đầy đủ cho <code>aghili2022addressing</code> và <code>niamh2021practica</code> (đọc full-text).</li><li>Sinh viên tự bổ sung ≥6 bài để đạt yêu cầu ≥10 bài của Rubric Milestone 1.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Mọi trích dẫn phải khớp key có thật trong <code>.bib</code> đã xác minh DOI qua Crossref API.</p></div>',8))])}const C=h(u,[["render",g]]);export{v as __pageData,C as default};
